      SUBROUTINE MPRINTCC     PRINT FLOOR COORDINATES, BEAM AND TRANSFER MATRICES AFTER C     EACH ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM38A.CIN'CC     LOCAL VARIABLESC      LOGICAL         BACC, BCOMB, BNORM, BSPEC       LOGICAL         SFO, TCOMB, TNORM, TSPEC, TYPEQ1CC--------------------------------------------------------------      IF (ONLY) GO TO 300      IF (TYPE .LE. 0) GO TO 300CC     PRINT COMPLETE ARBITRARY MATRIXC      IF (PRON .AND. ELPR .AND. TYPE .EQ. 14) THEN        CDB = 14        CALL RCOUT      ENDIFCC     PRINT BEAM ELLIPSE, TRANSFER MATRIX, AND COORDINATESC      IF (.NOT. NBE) GO TO 300      LCPR = .FALSE.      IF (.NOT. PRON) GO TO 300      BDUN = .FALSE.      TDUN = .FALSE.      IF (NRT) RDUN = .FALSE.      IF (.NOT. ELPR) GO TO 300      IF (LAY) CALL SURVEY      IF (SONLY) GO TO 300C      BACC = ACCEL .OR. LTWISS      IF ((BACC .OR. NORD1 .EQ. 1)     1    .AND. .NOT. RECENT) CALL BEAM      TYPEQ1 = TYPE .EQ. 1 .OR. TYPE .EQ. 12      SFO = SOFA .OR. NORD3 .GE. 1      BNORM = NOR .AND. .NOT. ACCEL      BSPEC = .NOT. NOR .AND. .NOT. BACC .AND. TYPEQ1 .AND. .NOT. SUPP      BCOMB = BNORM .OR. BSPEC      IF (LBEAM .AND. BCOMB .AND. SFO .AND. .NOT. BDUN) CALL QEOC      TNORM = TWP .OR. (NOR .AND. ACCEL)      TSPEC = .NOT. TWP .AND. BACC .AND. TYPEQ1 .AND. .NOT. SUPP      TCOMB = TNORM .OR. TSPEC      IF (LBEAM .AND. TCOMB .AND. SFO .AND. .NOT. TDUN) CALL TWISSC      IF (RAT .AND. NRT .AND. (TERSE .OR. SOFA .OR. NORD3 .GE. 1)     1    .AND. .NOT. RDUN) THEN        CDB = 6        CALL RCOUT      ENDIFC      TYPED = TYPE      IF (PLOT .AND. LPLOT .AND. NPASS .EQ. 2) CALL PLOTITC  300 RETURN      END